import sys, numpy as np
sys.path.insert(0,'/opt/tools'); import casa_tool
s=casa_tool.Session()
m,d=s.model,s.data
print('qpos',d.qpos[:15]); print('qvel',d.qvel[:15])
for name in ['mobilebase0_support','robot0_base','robot0_right_hand','robot0_right_gripper','gripper0_right_grip_site','gripper0_right_eef','stove_left_group_1_main','stove_left_group_1_knob_rear_left']:
 try:
  if name.startswith('gripper0'):
   i=m.site(name).id; print('site',name, 'pos',d.site_xpos[i], 'mat',d.site_xmat[i].reshape(3,3))
  else:
   i=m.body(name).id; print('body',name,'pos',d.xpos[i], 'quat',d.xquat[i])
 except Exception as e: print(name,e)
for name in ['stove_left_group_1_knob_rear_left','stove_left_group_1_knob_front_left','stove_left_group_1_knob_rear_center','stove_left_group_1_knob_rear_left_main']:
 try:
  b=m.body(name).id
  print('\nbody',name,'pos',d.xpos[b], 'quat',d.xquat[b], 'local pos',m.body_pos[b], 'parent',m.body(m.body_parentid[b]).name)
  for i in range(m.ngeom):
   if m.geom_bodyid[i]==b: print(' geom',m.geom(i).name,'pos',d.geom_xpos[i], 'size',m.geom_size[i], 'type',m.geom_type[i])
  for j in range(m.njnt):
   if m.jnt_bodyid[j]==b: print(' joint',m.joint(j).name,'axis',m.jnt_axis[j], 'pos',d.xanchor[j], 'qpos',d.qpos[m.jnt_qposadr[j]])
 except Exception as e: print(e)
print('eef ids',s.env.robots[0].eef_site_id)
print('robot base body',s.env.robots[0].robot_model.root_body)
